{"command": "curl -sL "https://en.wikipedia.org/wiki/P.A._Works" -H "User-Agent: Mozilla/5.0" 2>/dev/null | python3 -c "
import sys, re
html = sys.stdin.read()
# Find anime titles in television series section
section = re.search(r'Television series.*?(?=<h2>)', html, re.DOTALL)
if section:
    titles = re.findall(r'<i>(.*?)</i>', section)
    for t in titles[-20:]:
        print(t.strip())
" 2>/dev/null", "timeout": 15}
